def main():
    with open('pages/98.00_p120_Answers.html', 'r', encoding='utf-8') as f:
        html = f.read()

    soup = BeautifulSoup(html, 'html.parser')
    count = 0

    for li in soup.find_all('li'):
        if 'إجابة غير متوفرة' in str(li):
            ans_span = li.find('span', class_='highlight-green')
            if not ans_span: continue
            
            # Instead of exact matching the entire li text, let's normalize everything
            li_text = li.get_text()
            
            for k, v in answers.items():
                k_norm = k.replace(' ', '').replace('\\n', '').replace('ـ', '')
                li_norm = li_text.replace(' ', '').replace('\\n', '').replace('ـ', '')
                if k_norm in li_norm:
                    strong_tag = soup.new_tag('strong')
                    strong_tag.string = 'الْجَوَابُ: '
                    ans_span.clear()
                    ans_span.append(strong_tag)
                    ans_span.append(v)
                    count += 1
                    break
                    
    with open('pages/98.00_p120_Answers.html', 'w', encoding='utf-8') as f:
        f.write(str(soup))
        
    print('Replaced', count, 'answers via BS4 using exact norm matching!')

if __name__ == '__main__':
    main()
